from pathlib import Path
import json,time,hashlib,datetime,traceback
ROOT=Path.cwd(); N=ROOT/'docs/readings/2026-11-13-ssl-explicit-genera'; W=ROOT/'data/lexicon_builder/2026-11-12/ssl-explicit-genera/ssl-api-checkpoint'
def now():return datetime.datetime.now(datetime.timezone.utc).isoformat()
def save(path,value):
 tmp=path.with_name(path.name+'.tmp');tmp.write_text(json.dumps(value,indent=2)+'\n');tmp.replace(path)
def sha(path):
 h=hashlib.sha256()
 with path.open('rb') as f:
  for b in iter(lambda:f.read(8*1024*1024),b''):h.update(b)
 return h.hexdigest()
def pins():
 x=json.loads((N/'ssl-api-controller-source-freeze.json').read_text())
 bad=[p['path'] for p in x['pins'] if sha(ROOT/p['path'])!=p['sha256']]
 if bad:raise ValueError('OWNED_SOURCE_PINS_CHANGED:'+repr(bad))
 return x['pins']
phase=N/'ssl-api-controller-postwriter-phase.json'
try:
 save(phase,{'code':'WAITING_FOR_TEN_COORDINATE_WRITER_EXIT_AND_EXACT_H','updated_utc':now(),'lexical_writes':0,'model_service_calls':0,'activation_performed':False})
 deadline=time.monotonic()+3*3600
 prerequisites=[N/'ssl-api-controller-continuation-exit.json',N/'ssl-api-controller-prime-child-writer.json',W/'space-post-prime-child-teaching.json']
 while not all(p.exists() for p in prerequisites):
  if prerequisites[0].exists() and json.loads(prerequisites[0].read_text())['exit_code']!=0:raise ValueError('TEN_COORDINATE_WRITER_FAILED')
  if time.monotonic()>deadline:raise TimeoutError('TEN_COORDINATE_WRITER_PREREQUISITES_TIMEOUT_NO_WRITES')
  time.sleep(30)
 if json.loads(prerequisites[0].read_text())['exit_code']!=0:raise ValueError('TEN_COORDINATE_WRITER_FAILED')
 source_pins=pins(); db=W/'candidate.db'; before=sha(db)
 writer=json.loads(prerequisites[1].read_text())
 if writer['after_sha256']!=before or writer['new_model_service_calls']!=0 or writer['activation_performed']:raise ValueError('POSTWRITER_HEAD_IDENTITY_INVALID')
 save(phase,{'code':'FULL_POSTWRITER_REPLAY_RUNNING','updated_utc':now(),'candidate_sha256':before,'lexical_writes':0,'model_service_calls':0,'activation_performed':False})
 from GSE.curation.lexicon_builder.validation import validate_build
 from GSE.curation.lexicon_builder.evaluation import evaluate_build
 replay=validate_build(db);save(W/'postwriter-replay.json',replay)
 if replay['code']!='REPLAY_VALIDATED' or replay['entries_checked']!=401596 or replay['entries_validated']!=401596 or replay['entries_mismatched']!=0 or replay['inference_counts']['components_solver_limited']!=0 or not replay['complete_search']:raise ValueError('POSTWRITER_FULL_REPLAY_FAILED')
 gold=N/'sparse-release-021-gold.json'; evaluation=evaluate_build(db,gold);save(W/'postwriter-regression-gold.json',evaluation)
 outcomes=evaluation['outcomes']
 if outcomes.get('WRONG',0) or outcomes.get('NOT_FOUND',0) or not outcomes.get('IDENTIFIED_CORRECT',0):raise ValueError('POSTWRITER_REGRESSION_GOLD_FAILED')
 if sha(db)!=before:raise ValueError('POSTWRITER_DATABASE_CHANGED_DURING_READONLY_AUDIT')
 if pins()!=source_pins:raise ValueError('POSTWRITER_SOURCE_FREEZE_CHANGED_DURING_AUDIT')
 result={'format':'GSE.checkpoint-postwriter-validation/1','code':'POSTWRITER_REPLAY_AND_REGRESSION_VALIDATED_WORKLOAD_PENDING','updated_utc':now(),'candidate':str(db),'candidate_sha256':before,'replay':{'path':str(W/'postwriter-replay.json'),'sha256':sha(W/'postwriter-replay.json'),'entries_checked':replay['entries_checked'],'entries_validated':replay['entries_validated'],'entries_mismatched':replay['entries_mismatched'],'complete_search':replay['complete_search'],'inference_counts':replay['inference_counts']},'regression_gold':{'path':str(W/'postwriter-regression-gold.json'),'sha256':sha(W/'postwriter-regression-gold.json'),'gold_sha256':sha(gold),'outcomes':outcomes,'scope':'EXISTING_PUBLICATION_REGRESSION_NOT_FRESH_FINAL_GOLD'},'space_measurement':{'path':str(prerequisites[2]),'sha256':sha(prerequisites[2])},'builder_source_pins':source_pins,'lexical_writes':0,'new_model_service_calls':0,'runtime_workload_acceptance':'PENDING','usable_checkpoint_accepted':False,'activation_performed':False}
 save(W/'postwriter-validation.json',result);save(phase,result)
 save(N/'ssl-api-controller-postwriter-exit.json',{'exit_code':0,'finished_utc':now()})
except BaseException as error:
 save(phase,{'code':'POSTWRITER_VALIDATION_STOPPED','updated_utc':now(),'error_type':type(error).__name__,'error':str(error),'activation_performed':False})
 save(N/'ssl-api-controller-postwriter-exit.json',{'exit_code':1,'finished_utc':now(),'error_type':type(error).__name__,'error':str(error)})
 traceback.print_exc();raise
